import React, { useContext, useState } from 'react';
import { AuthContext } from '../context/AuthContext';
import { CartContext } from '../context/CartContext';
import AuthModal from './AuthModal';

const Navbar = ({ activeScreen, setActiveScreen, searchQuery, setSearchQuery }) => {
  const { user, logout } = useContext(AuthContext);
  const { cartItems, setIsDrawerOpen } = useContext(CartContext);
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [authModalMode, setAuthModalMode] = useState('customer_login');

  const totalCartCount = cartItems.reduce((acc, item) => acc + item.qty, 0);

  const openAuth = (mode) => {
    setAuthModalMode(mode);
    setAuthModalOpen(true);
  };

  const handleAuthSuccess = (role) => {
    if (role === 'admin') {
      setActiveScreen('admin');
    } else {
      setActiveScreen('home');
    }
  };

  return (
    <>
      <header style={{
        backgroundColor: '#ffffff',
        borderBottom: '1px solid #e2e8f0',
        position: 'sticky',
        top: 0,
        zIndex: 50,
        padding: '12px 24px',
      }}>
        <div style={{
          maxWidth: '1280px',
          margin: '0 auto',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '20px',
        }}>
          {/* Brand */}
          <div
            onClick={() => setActiveScreen('home')}
            style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px' }}
          >
            <div style={{
              width: '36px',
              height: '36px',
              borderRadius: '8px',
              background: 'linear-gradient(135deg, #0284c7, #0369a1)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#fff',
              fontWeight: 'bold',
              fontSize: '18px',
            }}>A</div>
            <span style={{ fontSize: '20px', fontWeight: '800', color: '#0f172a', letterSpacing: '-0.5px' }}>
              Aura<span style={{ color: '#0284c7' }}>Store</span>
            </span>
          </div>

          {/* Global Search Input */}
          <div style={{ flex: '1', maxWidth: '440px' }}>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search catalog, brand, specifications..."
              style={{
                width: '100%',
                padding: '8px 16px',
                borderRadius: '24px',
                border: '1px solid #cbd5e1',
                outline: 'none',
                fontSize: '14px',
                backgroundColor: '#f8fafc',
                boxSizing: 'border-box',
              }}
            />
          </div>

          {/* Navigation Actions */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
            <button
              onClick={() => setActiveScreen('home')}
              style={{
                background: 'none',
                border: 'none',
                fontWeight: activeScreen === 'home' ? '700' : '500',
                color: activeScreen === 'home' ? '#0284c7' : '#475569',
                fontSize: '14px',
                cursor: 'pointer',
              }}
            >
              Catalog
            </button>

            {user && user.role !== 'admin' && (
              <button
                onClick={() => setActiveScreen('orders')}
                style={{
                  background: 'none',
                  border: 'none',
                  fontWeight: activeScreen === 'orders' ? '700' : '500',
                  color: activeScreen === 'orders' ? '#0284c7' : '#475569',
                  fontSize: '14px',
                  cursor: 'pointer',
                }}
              >
                My Orders
              </button>
            )}

            {user?.role === 'admin' && (
              <button
                onClick={() => setActiveScreen('admin')}
                style={{
                  backgroundColor: activeScreen === 'admin' ? '#0284c7' : '#0f172a',
                  color: '#ffffff',
                  border: 'none',
                  padding: '7px 14px',
                  borderRadius: '6px',
                  fontWeight: '700',
                  fontSize: '13px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                }}
              >
                <span>⚡</span> Admin SKU Portal
              </button>
            )}

            {/* Authentication Buttons & User Status */}
            {!user ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <button
                  onClick={() => openAuth('customer_login')}
                  style={{
                    backgroundColor: '#ffffff',
                    border: '1px solid #cbd5e1',
                    padding: '7px 14px',
                    borderRadius: '8px',
                    fontWeight: '600',
                    color: '#334155',
                    fontSize: '13px',
                    cursor: 'pointer',
                  }}
                >
                  Sign In
                </button>
                <button
                  onClick={() => openAuth('admin_login')}
                  style={{
                    backgroundColor: '#0f172a',
                    border: 'none',
                    padding: '7px 12px',
                    borderRadius: '8px',
                    fontWeight: '600',
                    color: '#ffffff',
                    fontSize: '12px',
                    cursor: 'pointer',
                  }}
                  title="Store Administrator Console Login"
                >
                  Admin Portal
                </button>
              </div>
            ) : (
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <div style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-end',
                  fontSize: '12px',
                }}>
                  <span style={{ fontWeight: '700', color: '#0f172a' }}>{user.name}</span>
                  <span style={{
                    fontSize: '10px',
                    fontWeight: '800',
                    textTransform: 'uppercase',
                    color: user.role === 'admin' ? '#dc2626' : '#0284c7',
                  }}>
                    {user.role}
                  </span>
                </div>
                <button
                  onClick={logout}
                  style={{
                    backgroundColor: '#fee2e2',
                    border: '1px solid #fecaca',
                    padding: '5px 10px',
                    borderRadius: '6px',
                    color: '#991b1b',
                    fontWeight: '600',
                    fontSize: '12px',
                    cursor: 'pointer',
                  }}
                >
                  Logout
                </button>
              </div>
            )}

            {/* Cart Trigger */}
            <button
              onClick={() => setIsDrawerOpen(true)}
              style={{
                position: 'relative',
                backgroundColor: '#0284c7',
                color: '#ffffff',
                border: 'none',
                padding: '8px 16px',
                borderRadius: '20px',
                fontWeight: '600',
                fontSize: '13px',
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                cursor: 'pointer',
              }}
            >
              Cart
              {totalCartCount > 0 && (
                <span style={{
                  backgroundColor: '#ffffff',
                  color: '#0284c7',
                  borderRadius: '50%',
                  padding: '2px 7px',
                  fontSize: '11px',
                  fontWeight: '800',
                }}>
                  {totalCartCount}
                </span>
              )}
            </button>
          </div>
        </div>
      </header>

      {/* Auth Modal */}
      <AuthModal
        isOpen={authModalOpen}
        onClose={() => setAuthModalOpen(false)}
        initialMode={authModalMode}
        onSuccess={handleAuthSuccess}
      />
    </>
  );
};

export default Navbar;
